+"use strict";
+const pool = require("../database/connection");
+
+// Only routes explicitly designated as Android device-attested attendance paths
+// use this middleware. CRM web/manager authentication and recovery remain intact.
+// Never accept a client-supplied installation UUID as authentication.
+module.exports = async function requireActiveAndroidSession(req,res,next) {
+  const user = req.user || {};
+  const deviceId = user.android_device_id;
+  const familyId = user.android_session_family;
+  const uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
+  if (user.token_type !== "android_device" || !uuid.test(deviceId || "") || !uuid.test(familyId || "")) {
+    return res.status(401).json({success:false,code:"ANDROID_DEVICE_TOKEN_REQUIRED"});
+  }
+  try {
+    const result = await pool.query(
+      `SELECT 1 FROM user_devices d
+        JOIN android_refresh_sessions s
+          ON s.user_id=d.user_id AND s.company_id=d.company_id
+         AND s.device_id=d.device_id AND s.family_id=$4
+        WHERE d.user_id=$1 AND d.company_id=$2 AND d.device_id=$3
+          AND d.is_active=TRUE AND d.is_onboarded=TRUE
+          AND s.revoked_at IS NULL AND s.consumed_at IS NULL
+          AND s.expires_at>NOW()
+        LIMIT 1`,
+      [user.id,user.company_id,deviceId,familyId]
+    );
+    if (!result.rowCount) {
+      return res.status(403).json({success:false,code:"ANDROID_DEVICE_SESSION_REVOKED"});
+    }
+    // Enforce consistency when the mobile client supplies the installation ID.
+    const supplied = req.body?.device_id || req.query?.device_id;
+    if (supplied !== undefined && supplied !== deviceId) {
+      return res.status(403).json({success:false,code:"ANDROID_DEVICE_MISMATCH"});
+    }
+    req.androidDeviceId = deviceId;
+    return next();
+  } catch (error) {return next(error);}
+};

