+module.exports = function requireWebSession(req, res, next) {
+  const claims = req.user || {};
+  if (claims.token_type === "android_device" ||
+      claims.android_device_id || claims.android_session_family) {
+    return res.status(403).json({success:false,code:"WEB_SESSION_REQUIRED"});
+  }
+  return next();
+};

