+"use strict";
+
+// Isolated regression harness: no PostgreSQL connection, employee credentials,
+// environment file, or live attendance records are required.
+const test = require("node:test");
+const assert = require("node:assert/strict");
+const jwt = require("jsonwebtoken");
+
+const secret = "unit-test-secret-not-a-production-credential-123456";
+const poolPath = require.resolve("../src/database/connection");
+const authPath = require.resolve("../src/middleware/authMiddleware");
+
+async function invokeAuth(token, userRow) {
+  const originalSecret = process.env.JWT_SECRET;
+  const originalPoolCache = require.cache[poolPath];
+  const originalAuthCache = require.cache[authPath];
+  let queries = 0;
+  try {
+    process.env.JWT_SECRET = secret;
+    delete require.cache[authPath];
+    require.cache[poolPath] = {
+      id: poolPath, filename: poolPath, loaded: true,
+      exports: {query: async () => {
+        queries++;
+        return {rows: userRow ? [userRow] : []};
+      }}
+    };
+    const auth = require(authPath);
+    const req = {headers: {authorization: "Bearer " + token}};
+    const res = {
+      statusCode: 200,
+      status(n) {this.statusCode = n; return this;},
+      json(value) {this.body = value; return this;}
+    };
+    let nextCalled = false;
+    await auth(req, res, () => {nextCalled = true;});
+    return {status: res.statusCode, nextCalled, queries, user: req.user, body: res.body};
+  } finally {
+    if (originalSecret === undefined) delete process.env.JWT_SECRET;
+    else process.env.JWT_SECRET = originalSecret;
+    if (originalPoolCache) require.cache[poolPath] = originalPoolCache;
+    else delete require.cache[poolPath];
+    if (originalAuthCache) require.cache[authPath] = originalAuthCache;
+    else delete require.cache[authPath];
+  }
+}
+
+test("old device-unbound JWT is rejected by protected mobile attendance middleware", async () => {
+  const oldToken = jwt.sign({id:7, role:"Employee", company_id:1}, secret, {expiresIn:"1h"});
+  const outcome = await invokeAuth(oldToken, {is_active:true,password_changed_at:null});
+  assert.equal(outcome.nextCalled, true, "general CRM auth still accepts user identity for web/recovery");
+  assert.equal(outcome.user.android_device_id, undefined);
+  const middlewarePath = require.resolve("../src/middleware/requireActiveAndroidSession");
+  const previous = require.cache[middlewarePath];
+  try {
+    delete require.cache[middlewarePath];
+    const guard = require(middlewarePath);
+    const req = {user:outcome.user, body:{}, query:{}};
+    const res = {statusCode:200,status(n){this.statusCode=n;return this;},json(value){this.body=value;return this;}};
+    let accessAllowed=false;
+    await guard(req,res,()=>{accessAllowed=true;});
+    assert.equal(accessAllowed,false);
+    assert.equal(res.statusCode,401);
+    assert.equal(res.body.code,"ANDROID_DEVICE_TOKEN_REQUIRED");
+  } finally {
+    if(previous) require.cache[middlewarePath]=previous;
+    else delete require.cache[middlewarePath];
+  }
+});
+
