+const test = require('node:test');
+const assert = require('node:assert/strict');
+const fs = require('node:fs');
+const path = require('node:path');
+
+const root = path.join(__dirname, '..');
+const webOnly = require('../src/middleware/requireWebSession');
+const request = claims => ({ user: claims });
+function response() {
+  return {
+    statusCode: 200,
+    status(code) { this.statusCode = code; return this; },
+    json(body) { this.body = body; return this; }
+  };
+}
+
+test('web session route allows ordinary browser JWT and rejects Android device JWT', () => {
+  const allowed = response();
+  let called = false;
+  webOnly(request({id:7,role:'Manager',company_id:1}),allowed,()=>{called=true;});
+  assert.equal(called,true);
+  assert.equal(allowed.body,undefined);
+  const rejected=response();
+  webOnly(request({id:7,token_type:'android_device',android_device_id:'device'}),rejected,()=>{throw new Error('Android bypassed web boundary')});
+  assert.equal(rejected.statusCode,403);
+  assert.equal(rejected.body.code,'WEB_SESSION_REQUIRED');
+});
